SELECT CASE WHEN duration_sec >= 446 THEN 'high' WHEN duration_sec >= 142 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, ROUND((100 * SUM(CASE WHEN page = '/checkout' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_checkout FROM web_events WHERE duration_sec BETWEEN 126 AND 311 GROUP BY CASE WHEN duration_sec >= 446 THEN 'high' WHEN duration_sec >= 142 THEN 'mid' ELSE 'low' END HAVING pct_checkout < 69 ORDER BY duration_sec_bucket;
